def before = req.requirements(module).collect { it.ReqIFIdentifier } as Set
assert sections.every { section -> section.records.every { !before.contains(it.identifier) } }: 'This chunk was already imported; run 40-verify-submissions instead'
api.batch('Import submission items ' + 'des-2') {
    sections.each { section ->
        def folder = folders[section.folder]
        assert folder != null: 'Missing section folder ' + section.folder
        req.importRequirements(folder, section.records.collect { record -> record + [attributes: common + record.attributes] })
    }
}
def after = req.requirements(module).size()
assert after == before.size() + 39
log.info('Submission import chunk ' + 'des-2' + ' applied: ' + after + ' items in the module.')
return [chunk: 'des-2', imported: 39, items_in_module: after]
